/* AIVIC_FUNCTION_BUNDLE_START owner=determineAlgorithmReviewMeeting exports=determineAlgorithmReviewMeeting */
const __aivicBundle_5_determineAlgorithmReviewMeeting = (() => {
  function determineAlgorithmReviewMeeting(
    input: AlgorithmReviewMeetingInput
  ): AlgorithmReviewMeetingResult {
    const {
      currentTimestamp,
      meetingType,
      scheduledTime,
      targetDayOfWeek,
      targetBusinessDay,
      participantIds,
      attendanceConfirmations,
    } = input;
  
    // Parse scheduled time (HH:mm format)
    const [scheduledHour, scheduledMinute] = scheduledTime.split(':').map(Number);
  
    // Determine the target date based on meeting type
    let targetDate: Date;
  
    if (meetingType === 'weekly' && targetDayOfWeek !== undefined) {
      // Find the next occurrence of targetDayOfWeek at scheduledTime
      const currentDate = new Date(currentTimestamp);
      const currentDayOfWeek = currentDate.getUTCDay();
      let daysUntilTarget = targetDayOfWeek - currentDayOfWeek;
  
      if (daysUntilTarget < 0) {
        daysUntilTarget += 7;
      } else if (daysUntilTarget === 0) {
        // Same day - check if time has passed
        if (
          currentDate.getUTCHours() > scheduledHour ||
          (currentDate.getUTCHours() === scheduledHour &&
            currentDate.getUTCMinutes() > scheduledMinute)
        ) {
          daysUntilTarget = 7;
        }
      }
  
      targetDate = new Date(currentDate);
      targetDate.setUTCDate(targetDate.getUTCDate() + daysUntilTarget);
      targetDate.setUTCHours(scheduledHour, scheduledMinute, 0, 0);
    } else if (meetingType === 'monthly' && targetBusinessDay !== undefined) {
      // Find the Nth business day of the month at scheduledTime
      const currentDate = new Date(currentTimestamp);
      let targetMonth = currentDate.getUTCMonth();
      let targetYear = currentDate.getUTCFullYear();
  
      // Start from the first day of the target month
      let searchDate = new Date(Date.UTC(targetYear, targetMonth, 1));
      let businessDayCount = 0;
  
      while (businessDayCount < targetBusinessDay) {
        const dayOfWeek = searchDate.getUTCDay();
        // Business days: Monday (1) to Friday (5)
        if (dayOfWeek >= 1 && dayOfWeek <= 5) {
          businessDayCount++;
          if (businessDayCount === targetBusinessDay) {
            break;
          }
        }
        searchDate.setUTCDate(searchDate.getUTCDate() + 1);
      }
  
      targetDate = new Date(searchDate);
      targetDate.setUTCHours(scheduledHour, scheduledMinute, 0, 0);
    } else {
      targetDate = new Date(currentTimestamp);
      targetDate.setUTCHours(scheduledHour, scheduledMinute, 0, 0);
    }
  
    // Determine meeting status based on currentTimestamp
    const meetingStatus =
      currentTimestamp >= targetDate.getTime() ? 'scheduled' : 'pending';
  
    // Calculate attendance confirmation status
    let attendanceConfirmationStatus: 'confirmed_all' | 'partial' | 'pending' =
      'pending';
    let confirmedParticipantCount = 0;
    let confirmationCompletionRate = 0;
  
    if (attendanceConfirmations && attendanceConfirmations.length > 0) {
      confirmedParticipantCount = attendanceConfirmations.filter(
        (conf) => conf.status === 'confirmed'
      ).length;
  
      confirmationCompletionRate = Math.round(
        (confirmedParticipantCount / participantIds.length) * 100
      );
  
      if (confirmedParticipantCount === participantIds.length) {
        attendanceConfirmationStatus = 'confirmed_all';
      } else if (confirmedParticipantCount > 0) {
        attendanceConfirmationStatus = 'partial';
      }
    }
  
    const result: AlgorithmReviewMeetingResult = {
      meetingStatus,
      meetingType,
      scheduledDateTime: targetDate.toISOString(),
      participantCount: participantIds.length,
      attendanceNotificationsSent: true,
      notificationCount: participantIds.length,
    };
  
    if (attendanceConfirmations && attendanceConfirmations.length > 0) {
      result.attendanceConfirmationStatus = attendanceConfirmationStatus;
      result.confirmedParticipantCount = confirmedParticipantCount;
      result.confirmationCompletionRate = confirmationCompletionRate;
      result.processStatus = 'completed';
    } else if (meetingStatus === 'scheduled') {
      result.processStatus = 'completed';
    }
  
    return result;
  }
  return { determineAlgorithmReviewMeeting };
})();
