/* AIVIC_FUNCTION_BUNDLE_START owner=determineConferenceProceedingAndAssignAlternatives exports=determineConferenceProceedingAndAssignAlternatives */
const __aivicBundle_6_determineConferenceProceedingAndAssignAlternatives = (() => {
  function determineConferenceProceedingAndAssignAlternatives(
    input: ConferenceProposalInput,
  ): ConferenceProposalResult {
    if (input["conference_id"] === undefined || input["conference_id"] === null) { throw new Error("conference_id is required"); }
    const {
      conference_id,
      conference_type,
      scheduled_date,
      participants,
      available_alternatives,
    } = input;
  
    // Validate required conference_id
    if (!conference_id || String(conference_id).trim() === '') {
      throw new Error('conference_id is required');
    }
  
    // Determine if all participants are absent
    const allAbsent = participants.every((p) => p.status === 'absent');
  
    if (allAbsent) {
      // Calculate proposed reschedule date
      const proposedDate = new Date(scheduled_date);
      if (conference_type === 'weekly') {
        proposedDate.setDate(proposedDate.getDate() + 7);
      } else if (conference_type === 'monthly') {
        proposedDate.setMonth(proposedDate.getMonth() + 1);
      }
  
      // Assign alternatives to absent participants
      const assignedAlternatives = participants.map((participant, index) => {
        const alternative =
          available_alternatives[index % available_alternatives.length];
        return {
          original_participant_id: participant.participant_id,
          assigned_alternative_id: alternative.alternative_id,
          assignment_status: 'assigned',
          confirmation_required: true,
        };
      });
  
      const currentTimestamp = new Date();
  
      return {
        proceeding_status: 'postponed',
        reason: 'All participants are absent',
        alternative_assignment_invoked: true,
        assigned_alternatives: assignedAlternatives,
        notifications_created: true,
        notification_count: participants.length,
        proposed_reschedule_date: proposedDate,
        audit_trail_recorded: true,
        audit_entry: {
          action_type: 'CONFERENCE_POSTPONED',
          reason_code: 'ALL_PARTICIPANTS_ABSENT',
          timestamp: currentTimestamp,
        },
      };
    }
  
    // If at least one participant is confirmed, proceed with conference
    return {
      proceeding_status: 'proceed',
      alternative_assignment_invoked: false,
      assigned_alternatives: [],
      notifications_created: false,
      notification_count: 0,
      proposed_reschedule_date: scheduled_date,
      audit_trail_recorded: false,
      audit_entry: {
        action_type: 'CONFERENCE_PROCEEDED',
        reason_code: 'PARTICIPANTS_CONFIRMED',
        timestamp: new Date(),
      },
    };
  }
  return { determineConferenceProceedingAndAssignAlternatives };
})();
