const __aivicBundle_7_validateMeetingParticipants = (() => {
  function validateMeetingParticipants(
    input: MeetingParticipantValidationInput
  ): MeetingParticipantValidationResult {
    if (input["scheduledDate"] === undefined || input["scheduledDate"] === null) { throw new Error("scheduledDate is required"); }
    // participants が null、undefined、または配列でない場合はエラー
    if (
      input.participants === null ||
      input.participants === undefined ||
      !Array.isArray(input.participants)
    ) {
      throw new Error('参加予定者データが不正な形式です');
    }
  
    // participants が空配列の場合はエラー
    if (input.participants.length === 0) {
      throw new Error('参加予定者が1人以上必要です');
    }
  
    // 各 participant の必須フィールド（userId、role）を検証
    for (const participant of input.participants) {
      if (
        !participant.userId ||
        typeof participant.userId !== 'string' ||
        participant.userId.trim() === ''
      ) {
        throw new Error('参加予定者のユーザーIDが不正です');
      }
  
      if (
        !participant.role ||
        typeof participant.role !== 'string' ||
        participant.role.trim() === ''
      ) {
        throw new Error('参加予定者のロールが不正です');
      }
    }
  
    // 検証成功時の結果を返す
    return {
      isValid: true,
      meetingId: input.meetingId,
      participantCount: input.participants.length,
      validationStatus: 'success',
    };
  }
  return { validateMeetingParticipants };
})();
