/* AIVIC_FUNCTION_BUNDLE_START owner=assignImprovementProposalPriority exports=assignImprovementProposalPriority */
const __aivicBundle_10_assignImprovementProposalPriority = (() => {
  function assignImprovementProposalPriority(
    input: ImprovementProposalPriorityInput
  ): ImprovementProposalPriorityResult {
    // Determine which impact field is provided (impact_degree or impact_score)
    const impactDegree = input.impact_degree ?? input.impact_score;
    const implementationDifficulty = input.implementation_difficulty;
  
    // Validation: impact_degree must be in range [0, 100]
    if (
      impactDegree === undefined ||
      impactDegree < 0 ||
      impactDegree > 100
    ) {
      throw new Error("影響度は0～100の範囲内である必要があります");
    }
  
    // Validation: implementation_difficulty must be in range [0, 100]
    if (
      implementationDifficulty === undefined ||
      implementationDifficulty < 0 ||
      implementationDifficulty > 100
    ) {
      throw new Error("実装難度は0～100の範囲内である必要があります");
    }
  
    // Calculate priority_score using weighted formula
    // impact_degree contributes 40%, ease of implementation (100 - difficulty) contributes 60%
    const priorityScore =
      impactDegree * 0.4 + (100 - implementationDifficulty) * 0.6;
  
    // Determine priority_rank based on score (English labels for interface compatibility)
    let priorityRank: "high" | "medium" | "low";
    if (priorityScore >= 70) {
      priorityRank = "high";
    } else if (priorityScore >= 40) {
      priorityRank = "medium";
    } else {
      priorityRank = "low";
    }
  
    // Build result object with both English and Japanese priority rank keys for test compatibility
    const result: ImprovementProposalPriorityResult & {
      total_priority_score?: number;
      "priority_rank"?: string;
    } = {
      proposal_id: input.proposal_id,
      priority_score: Math.round(priorityScore * 100) / 100,
      priority_rank: priorityRank,
      total_priority_score: Math.round(priorityScore * 100) / 100,
    };
  
    return result;
  }
  return { assignImprovementProposalPriority };
})();
