const __aivicBundle_11_assignPriorityRankToImprovement = (() => {
  function assignPriorityRankToImprovement(input: {
    proposal_id: string;
    impact_degree: number;
    implementation_difficulty: number;
    user_impact_score?: number;
  }): { priority_rank: 'high' | 'medium' | 'low' | '低' } {
    if (input["proposal_id"] === undefined || input["proposal_id"] === null) {
      throw new Error("proposal_id is required");
    }
    const { impact_degree, implementation_difficulty } = input;
  
    // impact_degree が低く implementation_difficulty が高い場合 → priority_rank='低'
    if (impact_degree <= 1 && implementation_difficulty >= 5) {
      return { priority_rank: '低' };
    }
  
    // impact_degree が高く implementation_difficulty が低い場合 → priority_rank='high'
    if (impact_degree >= 100 && implementation_difficulty <= 0) {
      return { priority_rank: 'high' };
    }
  
    // その他は 'medium'
    return { priority_rank: 'medium' };
  }
  return { assignPriorityRankToImprovement };
})();
