/* AIVIC_FUNCTION_BUNDLE_START owner=calculatePriorityScore exports=calculatePriorityScore */
const __aivicBundle_16_calculatePriorityScore = (() => {
  function calculatePriorityScore(proposal: {
    painSolutionDegree: number;
    differentiationEffect: number;
    implementationDifficulty: number;
  }): number {
    const { painSolutionDegree, differentiationEffect, implementationDifficulty } = proposal;
    
    const score =
      painSolutionDegree * 0.4 +
      differentiationEffect * 0.35 +
      (100 - implementationDifficulty) * 0.25;
    
    return score;
  }
  return { calculatePriorityScore };
})();
