const __aivicBundle_17_calculateImprovementProposalPriorityScore = (() => {
  function calculateImprovementProposalPriorityScore(proposal: {
    proposalId: string;
    businessValue: number;
    technicalDifficulty: number;
    userImpact: number;
  }): number {
    if (proposal["proposalId"] === undefined || proposal["proposalId"] === null) { throw new Error("proposalId is required"); }
    const { businessValue, technicalDifficulty, userImpact } = proposal;
  
    if (businessValue <= 0 || technicalDifficulty < 0 || userImpact < 0) {
      throw new Error('評価指標は正の数である必要があります');
    }
  
    const priorityScore = ((businessValue + userImpact) / (technicalDifficulty + 1)) * 10;
  
    return priorityScore;
  }
  return { calculateImprovementProposalPriorityScore };
})();
