/* AIVIC_FUNCTION_BUNDLE_START owner=generatePainFactorPriorityMatrix exports=generatePainFactorPriorityMatrix */
const __aivicBundle_18_generatePainFactorPriorityMatrix = (() => {
  function generatePainFactorPriorityMatrix(
    interviewRecords: Array<{ pain_factor_category: string; occurrence_count: number }>,
    appLogEntries: Array<{ pain_factor_category: string; operation_log_count: number; impact_level: string }>
  ): {
    pain_factors: Array<{ pain_factor_category: string; occurrence_frequency: number; impact_level: string; priority_rank: number }>;
    priority_matrix: PriorityMatrixData;
    matrix_generated_at: string;
    quantification_status: string;
  } {
    const painFactorMap = new Map<string, { occurrence_frequency: number; impact_level: string }>();
  
    for (const record of interviewRecords) {
      const existing = painFactorMap.get(record.pain_factor_category) || { occurrence_frequency: 0, impact_level: '' };
      painFactorMap.set(record.pain_factor_category, {
        occurrence_frequency: existing.occurrence_frequency + record.occurrence_count,
        impact_level: existing.impact_level,
      });
    }
  
    for (const entry of appLogEntries) {
      const existing = painFactorMap.get(entry.pain_factor_category) || { occurrence_frequency: 0, impact_level: '' };
      painFactorMap.set(entry.pain_factor_category, {
        occurrence_frequency: existing.occurrence_frequency + entry.operation_log_count,
        impact_level: entry.impact_level,
      });
    }
  
    const painFactorsArray = Array.from(painFactorMap.entries()).map(([category, data]) => ({
      pain_factor_category: category,
      occurrence_frequency: data.occurrence_frequency,
      impact_level: data.impact_level,
    }));
  
    painFactorsArray.sort((a, b) => b.occurrence_frequency - a.occurrence_frequency);
  
    const painFactorsWithRank = painFactorsArray.map((pf, index) => ({
      pain_factor_category: pf.pain_factor_category,
      occurrence_frequency: pf.occurrence_frequency,
      impact_level: pf.impact_level,
      priority_rank: index + 1,
    }));
  
    const highPriorityZone: Array<{ pain_factor_category: string }> = [];
    const mediumPriorityZone: Array<{ pain_factor_category: string }> = [];
    const lowPriorityZone: Array<{ pain_factor_category: string }> = [];
  
    for (const pf of painFactorsWithRank) {
      if (pf.impact_level === 'high') {
        highPriorityZone.push({ pain_factor_category: pf.pain_factor_category });
      } else if (pf.impact_level === 'medium') {
        mediumPriorityZone.push({ pain_factor_category: pf.pain_factor_category });
      } else if (pf.impact_level === 'low') {
        lowPriorityZone.push({ pain_factor_category: pf.pain_factor_category });
      }
    }
  
    const priorityMatrix: PriorityMatrixData = {
      high_priority_zone: highPriorityZone,
      medium_priority_zone: mediumPriorityZone,
      low_priority_zone: lowPriorityZone,
    };
  
    return {
      pain_factors: painFactorsWithRank,
      priority_matrix: priorityMatrix,
      matrix_generated_at: new Date().toISOString(),
      quantification_status: 'completed',
    };
  }
  return { generatePainFactorPriorityMatrix };
})();
export const generatePainFactorPriorityMatrix = __aivicBundle_18_generatePainFactorPriorityMatrix.generatePainFactorPriorityMatrix;
/* AIVIC_FUNCTION_BUNDLE_END owner=generatePainFactorPriorityMatrix */

