/* AIVIC_FUNCTION_BUNDLE_START owner=validateAgeSegmentationSchema exports=validateAgeSegmentationSchema */
const __aivicBundle_25_validateAgeSegmentationSchema = (() => {
  function validateAgeSegmentationSchema(criteria: SegmentationCriteria): { isValid: boolean; errors: string[] } {
    if (criteria["targetSegment"] === undefined || criteria["targetSegment"] === null) { throw new Error("targetSegment is required"); }
    if (criteria["familyCompositionAxis"] === undefined || criteria["familyCompositionAxis"] === null) { throw new Error("familyCompositionAxis is required"); }
    if (criteria["dietaryRestrictionAxis"] === undefined || criteria["dietaryRestrictionAxis"] === null) { throw new Error("dietaryRestrictionAxis is required"); }
    const errors: string[] = [];
  
    // Validate ageAxisCategories exists and is an array
    if (!criteria.ageAxisCategories || !Array.isArray(criteria.ageAxisCategories)) {
      errors.push("ageAxisCategories must be an array");
      return { isValid: false, errors };
    }
  
    if (criteria.ageAxisCategories.length === 0) {
      errors.push("ageAxisCategories must not be empty");
      return { isValid: false, errors };
    }
  
    // Validate each category
    for (let i = 0; i < criteria.ageAxisCategories.length; i++) {
      const category = criteria.ageAxisCategories[i];
  
      // Validate minAge < maxAge
      if (typeof category.minAge !== "number" || typeof category.maxAge !== "number") {
        errors.push(`Category ${i}: minAge and maxAge must be numbers`);
        continue;
      }
  
      if (category.minAge >= category.maxAge) {
        errors.push(`Category ${i}: minAge must be less than maxAge`);
      }
  
      // Validate minAge >= 0
      if (category.minAge < 0) {
        errors.push(`Category ${i}: minAge must be non-negative`);
      }
    }
  
    // Validate no overlaps and continuity
    const sortedCategories = [...criteria.ageAxisCategories].sort((a, b) => a.minAge - b.minAge);
  
    for (let i = 0; i < sortedCategories.length - 1; i++) {
      const current = sortedCategories[i];
      const next = sortedCategories[i + 1];
  
      // Check for overlap
      if (current.maxAge > next.minAge) {
        errors.push(`Overlap detected between category "${current.id}" and "${next.id}"`);
      }
  
      // Check for gap (non-continuous)
      if (current.maxAge < next.minAge) {
        errors.push(`Gap detected between category "${current.id}" (maxAge: ${current.maxAge}) and "${next.id}" (minAge: ${next.minAge})`);
      }
    }
  
    return {
      isValid: errors.length === 0,
      errors,
    };
  }
  return { validateAgeSegmentationSchema };
})();
export const validateAgeSegmentationSchema = __aivicBundle_25_validateAgeSegmentationSchema.validateAgeSegmentationSchema;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateAgeSegmentationSchema */

