/* AIVIC_FUNCTION_BUNDLE_START owner=prioritizeSegmentsByMaxDifferentiationEffect exports=prioritizeSegmentsByMaxDifferentiationEffect */
const __aivicBundle_31_prioritizeSegmentsByMaxDifferentiationEffect = (() => {
  function prioritizeSegmentsByMaxDifferentiationEffect(
    segments: Array<{
      segmentId: string;
      segmentName: string;
      successRate: number;
      satisfactionScore: number;
      occurrenceFrequency: number;
    }>
  ): Array<{
    segmentId: string;
    segmentName: string;
    successRate: number;
    satisfactionScore: number;
    occurrenceFrequency: number;
    priorityScore: number;
  }> {
    const maxOccurrenceFrequency = Math.max(
      ...segments.map((s) => s.occurrenceFrequency),
      1
    );
  
    const withPriorityScore = segments.map((segment) => {
      const baseScore = (segment.successRate + segment.satisfactionScore) / 2;
      const normalizedFrequency = segment.occurrenceFrequency / maxOccurrenceFrequency;
      const priorityScore = Math.round(baseScore + normalizedFrequency);
  
      return {
        ...segment,
        priorityScore,
      };
    });
  
    const sorted = withPriorityScore.sort((a, b) => {
      const priorityDiff = b.priorityScore - a.priorityScore;
      if (priorityDiff !== 0) {
        return priorityDiff;
      }
      return b.occurrenceFrequency - a.occurrenceFrequency;
    });
  
    return sorted;
  }
  return { prioritizeSegmentsByMaxDifferentiationEffect };
})();
