/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeSegmentDifferentiationPriority exports=analyzeSegmentDifferentiationPriority */
const __aivicBundle_32_analyzeSegmentDifferentiationPriority = (() => {
  function analyzeSegmentDifferentiationPriority(segmentData: any): { segmentId: string; priorityScore: number; priorityRank: string } {
    // 必須フィールドの定義
    const requiredFields = [
      'segmentId',
      'generationSuccessRate',
      'cookingTimeReductionRate',
      'userSatisfactionScore',
      'segmentSize',
      'differentiationImpact'
    ];
  
    // 空オブジェクトチェック
    if (!segmentData || Object.keys(segmentData).length === 0) {
      throw new Error('データ妥当性エラー: セグメントデータが空です');
    }
  
    // 必須フィールドの存在確認
    for (const field of requiredFields) {
      if (!(field in segmentData)) {
        throw new Error(`必須フィールド「${field}」が不足しています`);
      }
    }
  
    // 各フィールドの値を取得
    const {
      segmentId,
      generationSuccessRate,
      cookingTimeReductionRate,
      userSatisfactionScore,
      segmentSize,
      differentiationImpact
    } = segmentData;
  
    // null チェック
    if (
      generationSuccessRate === null ||
      cookingTimeReductionRate === null ||
      userSatisfactionScore === null ||
      segmentSize === null ||
      differentiationImpact === null
    ) {
      throw new Error('無効な値: null が含まれています');
    }
  
    // 型チェック（数値フィールド）
    if (
      typeof generationSuccessRate !== 'number' ||
      typeof cookingTimeReductionRate !== 'number' ||
      typeof userSatisfactionScore !== 'number' ||
      typeof segmentSize !== 'number'
    ) {
      throw new Error('型不正: 数値フィールドが正しい型ではありません');
    }
  
    // 型チェック（文字列フィールド）
    if (typeof segmentId !== 'string' || typeof differentiationImpact !== 'string') {
      throw new Error('型不正: 文字列フィールドが正しい型ではありません');
    }
  
    // 優先度スコアの計算
    // 成功率（0-100）、調理時間短縮率（0-100）、満足度（0-5を0-100に正規化）、セグメントサイズ（相対的な重み）を組み合わせ
    const normalizedSatisfaction = (userSatisfactionScore / 5) * 100;
    const sizeWeight = Math.min(segmentSize / 200, 1); // セグメントサイズを0-1に正規化
  
    const priorityScore =
      (generationSuccessRate * 0.35 +
        cookingTimeReductionRate * 0.25 +
        normalizedSatisfaction * 0.25 +
        sizeWeight * 100 * 0.15) *
      (differentiationImpact === 'high' ? 1.0 : differentiationImpact === 'medium' ? 0.85 : 0.7);
  
    // 優先度ランクの決定
    let priorityRank: string;
    if (priorityScore >= 70) {
      priorityRank = 'high';
    } else if (priorityScore >= 40) {
      priorityRank = 'medium';
    } else {
      priorityRank = 'low';
    }
  
    return {
      segmentId,
      priorityScore: Math.round(priorityScore * 100) / 100,
      priorityRank
    };
  }
  return { analyzeSegmentDifferentiationPriority };
})();
